def weightedLinesTotalReceipt(links, k):
    a=links
    out=[]
    import heapq
    n=len(a)
    dist=[float('inf')]*n
    heap=[]
    if n:
        dist[0]=0
        heap=[(0,0)]
    while heap:
        cost,u=heapq.heappop(heap)
        if cost!=dist[u]: continue
        for v in range(n):
            if a[u][v]>0 and cost+a[u][v]<dist[v]:
                dist[v]=cost+a[u][v]
                heapq.heappush(heap,(dist[v],v))
    out=[d if d!=float('inf') else -1 for d in dist]
    return sum(out)

