def cableFamiliesProofStrip(links, k):
    a=links
    out=[]
    n=len(a)
    parent=list(range(n))
    size=[1]*n
    def find(x):
        while parent[x]!=x:
            parent[x]=parent[parent[x]]
            x=parent[x]
        return x
    for u in range(n):
        for v in range(u+1,n):
            if a[u][v]:
                x,y=find(u),find(v)
                if x!=y:
                    if size[x]<size[y]: x,y=y,x
                    parent[y]=x
                    size[x]+=size[y]
    out=[size[find(v)] for v in range(n)]
    return out

